/* Independent BLUE external response panel. */
(function(root){'use strict';
  function mount(doc,host){host=host||doc.getElementById('document-blue-workbench')||doc.getElementById('document-blue');if(!host||doc.getElementById('external-blue'))return;
    const node=(tag,text)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
    const section=node('section');section.id='external-blue';section.className='role-step external-blue';const status=node('p');status.setAttribute('role','status');
    const button=(text,fn)=>{const b=node('button',text);b.type='button';b.className='button secondary';b.addEventListener('click',fn);return b;};
    const bridge=()=>root.FalsifyDocumentBlueExternal,source=()=>bridge()?.getSource();
    const instructionsUI=root.FalsifyPromptInstructions?.mount(doc,'blue',source,status);
    const answer=node('textarea');answer.rows=8;answer.setAttribute('aria-label','BLUE 외부 응답');
    const file=node('input');file.type='file';file.accept='.json,.txt,.md,application/json,text/plain,text/markdown';file.setAttribute('aria-label','BLUE 응답 파일');file.addEventListener('change',async()=>{try{if(file.files[0]){const prior=source(),identity=prior&&prior.fileHash+':'+(prior.sourceHash||'');const raw=await file.files[0].text(),current=source();if(!current||identity!==current.fileHash+':'+(current.sourceHash||'')){status.textContent='파일 읽는 동안 원문이 바뀌어 가져오지 않았습니다.';return;}answer.value=raw;importButton.click();}}catch(e){status.textContent='파일을 읽지 못했습니다: '+e.message;}});
    const list=node('div');let boxes=new Map();function render(snapshot){const focused=doc.activeElement?.externalItemId;boxes=new Map();list.replaceChildren();for(const batch of snapshot?.batches||[])if(batch.report)list.append(node('p','검토 보고: '+batch.report));for(const item of snapshot?.items||[]){const card=node('article');const label=node('label');label.className='check-row';const box=node('input');box.type='checkbox';box.externalItemId=item.id;boxes.set(item.id,box);box.checked=!!item.enabled;box.addEventListener('change',()=>{try{bridge().setEnabled(item.id,box.checked);}catch(e){status.textContent=e.message;}});label.append(box,node('span',item.rationale||item.quote||'지적'));card.append(label);for(const [key,label] of [['findingType','유형'],['severity','심각도'],['confidence','확신도'],['locationLabel','위치'],['reportNumber','번호']])if(item[key]!=null&&item[key]!=='')card.append(node('p',label+': '+item[key]));if(item.quote)card.append(node('p','인용: '+item.quote));if(item.matchStatus!=='matched'&&item.matches?.length){const choice=(m,i)=>{const group=node('div'),actual=m.before??source()?.segments.find(s=>s.id===m.segmentId)?.text.slice(m.start,m.end);group.append(node('p',(Number.isInteger(m.pageIndex)?(m.pageIndex+1)+'쪽 · ':'')+'원문 후보 '+(i+1)),node('blockquote',actual||''),button(i===0?'이 위치에 연결':'이 후보에 연결',()=>{try{bridge().bind(item.id,{segmentId:m.segmentId,pageIndex:m.pageIndex,anchor:{start:m.start,end:m.end},before:actual});}catch(e){status.textContent=e.message;}}));return group;};card.append(choice(item.matches[0],0));if(item.matches.length>1){const more=node('details');more.append(node('summary','다른 위치 후보'));item.matches.slice(1).forEach((m,i)=>more.append(choice(m,i+1)));card.append(more);}}const binding=node('details');binding.append(node('summary','원문 위치 직접 선택'));const chooser=node('select');chooser.setAttribute('aria-label','원문 문단');const parts=source()?.segments||[];for(const part of parts){const option=node('option',part.label||part.id);option.value=part.id;chooser.append(option);}const excerpt=node('textarea');excerpt.rows=4;excerpt.readOnly=true;excerpt.setAttribute('aria-label','위치로 지정할 원문을 선택하세요');const update=()=>{excerpt.value=parts.find(p=>p.id===chooser.value)?.text||'';};chooser.addEventListener('change',update);update();binding.append(chooser,excerpt,button('선택한 원문에 연결',()=>{try{const start=excerpt.selectionStart,end=excerpt.selectionEnd,segment=parts.find(p=>p.id===chooser.value);if(!segment||start===end)throw Error('원문에서 연결할 부분을 선택하세요.');bridge().bind(item.id,{segmentId:segment.id,pageIndex:segment.pageIndex??parts.indexOf(segment),anchor:{start,end},before:segment.text.slice(start,end)});}catch(e){status.textContent=e.message;}}));card.append(binding);if(item.evidence?.length)card.append(node('p','근거: '+item.evidence.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('; ')));if(item.references?.length)card.append(node('p','참고: '+item.references.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('; ')));list.append(card);}if(focused)boxes.get(focused)?.focus();}
    doc.addEventListener('falsify:blue-external-responses',e=>render(e.detail));let sourceIdentity=null;doc.addEventListener('falsify:blue-state',()=>{const s=source(),next=s?s.fileHash+':'+s.sourceHash:null;if(sourceIdentity!==null&&next!==sourceIdentity){answer.value='';file.value='';status.textContent='원문이 바뀌어 입력을 지웠습니다.';}sourceIdentity=next;render(bridge()?.getExternalResponses());});
    const importButton=button('응답 가져오기',()=>{const s=source();if(!s){status.textContent='먼저 BLUE 파일을 선택하세요.';return;}try{const batch=root.FalsifyExternalExchange.parse(answer.value,{role:'blue',...s,prompt:instructionsUI?.requested()});if(batch.diagnostics.some(d=>d.code==='role-mismatch'))throw Error('응답의 역할이 다릅니다.');if(batch.diagnostics.some(d=>d.code==='file-hash-mismatch')&&!root.confirm('응답의 원문 식별이 다릅니다. 현재 원문에 가져올까요?'))return;render(bridge().acceptExternalResponse(batch));status.textContent='응답 저장 · 지적 '+batch.items.length+'개. '+batch.diagnostics.map(d=>d.message).join(' ');}catch(e){status.textContent='가져오지 못했습니다: '+e.message;}});
    const record=button('선택한 지적 기록',async()=>{try{const id=await bridge().record();status.textContent='기록됨 · '+id;}catch(e){status.textContent='기록하지 못했습니다: '+e.message;}});
    const saved=node('div');const showSaved=button('이 파일의 기록 보기',()=>{saved.replaceChildren();try{for(const r of bridge().records()){saved.append(button(new Date(r.createdAt).toLocaleString()+' 기록 복원',()=>{try{bridge().restore(r.snapshot);render(bridge().getExternalResponses());status.textContent='기록을 복원했습니다.';}catch(e){status.textContent='복원하지 못했습니다: '+e.message;}}));}if(!saved.childNodes.length)status.textContent='이 파일의 기록이 없습니다.';}catch(e){status.textContent=e.message;}});
    answer.addEventListener('paste',e=>{const text=e.clipboardData?.getData('text');if(typeof text==='string'){e.preventDefault();answer.value=text;importButton.click();}});section.append(node('h2','외부 BLUE 응답 가져오기'),node('p','응답을 붙여넣거나 파일을 선택하세요. 여러 응답을 함께 보관합니다.'));if(instructionsUI)section.append(instructionsUI.panel);section.append(answer,file,importButton,list,record,showSaved,saved,status);host.append(section);render(bridge()?.getExternalResponses());return section;
  }
  root.FalsifyExternalBlueUI={mount};if(root.document)mount(root.document);
})(typeof globalThis==='object'?globalThis:this);
